    <script>
        $(function () {
            @if($isInventoryPurchase)
            $('.js-purchase-post[data-label="Post"]').remove();
            @endif
            function request($button, data) {
                if ($button.data('submitting')) return;
                $button.data('submitting', true).prop('disabled', true);
                $.ajax({ url:$button.data('url'), method:'POST', data:data, headers:{ Accept:'application/json', 'X-CSRF-TOKEN':$('meta[name="csrf-token"]').attr('content') } })
                    .done(function (response) { Swal.fire({ icon:'success', text:response.msg }).then(function () { location.reload(); }); })
                    .fail(function (xhr) { var response=xhr.responseJSON||{}, errors=response.errors||{}; Swal.fire({ icon:'error', text:(errors.posting_date||errors.reason||errors.status||errors.account_mapping||errors.lines||[response.message||'ไม่สามารถดำเนินการได้'])[0] }); })
                    .always(function () { $button.data('submitting', false).prop('disabled', false); });
            }
            $('.js-purchase-delete').on('click', function () { var $button=$(this); Swal.fire({ title:'ลบร่างเอกสารซื้อ?', text:'ลบได้เฉพาะเอกสารที่ยังเป็นร่างก่อนอนุมัติ', icon:'warning', showCancelButton:true, confirmButtonText:'ลบเอกสาร', cancelButtonText:'ยกเลิก' }).then(function(result){ if(!result.isConfirmed)return; $button.prop('disabled',true); $.ajax({url:$button.data('url'),method:'DELETE',data:{_token:$('meta[name="csrf-token"]').attr('content')}}).done(function(response){ Swal.fire({icon:'success',text:response.msg}).then(function(){window.location='{{ route($moduleRoutePrefix.'.purchase-documents.index') }}';}); }).fail(function(xhr){ var errors=(xhr.responseJSON||{}).errors||{}; Swal.fire({icon:'error',text:(errors.status||['ลบเอกสารไม่สำเร็จ'])[0]}); $button.prop('disabled',false); }); }); });
            $('.js-purchase-action').on('click', function () { var $button=$(this), approve=$button.data('label')==='อนุมัติ', options={title:$button.data('label')+'เอกสาร',showCancelButton:true,confirmButtonText:$button.data('label'),cancelButtonText:'ยกเลิก'}; if(!approve){options.input='textarea';options.inputLabel='เหตุผล (อย่างน้อย 10 ตัวอักษร)';options.preConfirm=function(reason){reason=$.trim(reason||'');if(reason.length<10){Swal.showValidationMessage('กรุณาระบุเหตุผลอย่างน้อย 10 ตัวอักษร');return false;}return reason;};} Swal.fire(options).then(function(result){if(result.isConfirmed)request($button,{reason:approve?'':result.value});}); });
            $('.js-purchase-post').on('click', function () { var $button=$(this), minimum=$button.data('document-date'), today=@json(today()->format('Y-m-d')); Swal.fire({ title:'Post เอกสาร', input:'date', inputLabel:'วันที่ Post', inputValue:today<minimum?minimum:today, inputAttributes:{min:minimum}, showCancelButton:true, confirmButtonText:'Post' }).then(function(result){if(result.isConfirmed) request($button,{posting_date:result.value});}); });
            $('.js-purchase-reverse').on('click', function () { var $button=$(this), minimum=$button.data('document-date'), today=@json(today()->format('Y-m-d')); Swal.fire({ title:'กลับรายการ Inventory', input:'textarea', inputLabel:'เหตุผล (อย่างน้อย 10 ตัวอักษร)', showCancelButton:true, confirmButtonText:'กลับรายการ', preConfirm:function(reason){reason=$.trim(reason||''); if(reason.length<10){Swal.showValidationMessage('กรุณาระบุเหตุผลอย่างน้อย 10 ตัวอักษร'); return false;} return reason;} }).then(function(result){if(result.isConfirmed) request($button,{reversal_date:today<minimum?minimum:today, reason:result.value});}); });
            $('.js-variance-action').on('click', function () { var $button=$(this); Swal.fire({ title:$button.data('label'), input:'textarea', inputLabel:'เหตุผล (อย่างน้อย 10 ตัวอักษร)', showCancelButton:true, confirmButtonText:$button.data('label'), preConfirm:function(reason){reason=$.trim(reason||''); if(reason.length<10){Swal.showValidationMessage('กรุณาระบุเหตุผลอย่างน้อย 10 ตัวอักษร'); return false;} return reason;} }).then(function(result){if(result.isConfirmed) request($button,{reason:result.value});}); });
        });
    </script>
@endpush
